package com.thakur.employee.config; import com.thakur.employee.model.*;import com.thakur.employee.repository.UserRepository;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder; @Configuration public class DataSeeder {@Bean CommandLineRunner seed(UserRepository r,PasswordEncoder e){return args->{create(r,e,"Employee Demo","employee@demo.com","Engineering",Role.EMPLOYEE);create(r,e,"Manager Demo","manager@demo.com","Engineering",Role.MANAGER);create(r,e,"Finance Demo","finance@demo.com","Finance",Role.FINANCE);create(r,e,"Admin Demo","admin@demo.com","Administration",Role.ADMIN);};}private void create(UserRepository r,PasswordEncoder e,String n,String mail,String dept,Role role){if(!r.existsByEmail(mail))r.save(AppUser.builder().name(n).email(mail).password(e.encode("Password@123")).department(dept).role(role).build());}}
